from .common_oam import CommonOAM
from .megazone_oam import MegaZoneOAM
from moler.exceptions import ExecutionException


class Rest(object):

    oam_type = None

    def __new__(cls, gnb_class_object=None, oam_ip=None, oam_type='COAM', device_name='GNB0', *args, **kwargs):

        if Rest.oam_type is None:
            if gnb_class_object is None:
                try:
                    Rest.oam_type = Rest._get_oam_type_from_airscale(device_name)
                except ExecutionException:
                    Rest.oam_type = oam_type
            else:
                Rest.oam_type = gnb_class_object.oam_type

        instance = super(Rest, cls).__new__(Rest._get_oam_class_name())

        if hasattr(cls, '__init__'):
            instance.__init__(oam_ip=oam_ip, *args, **kwargs)

        return instance

    def __init__(self, oam_ip, mrbts_id=None, nrbts_id=None):
        pass

    @staticmethod
    def _get_oam_type_from_airscale(device_name):
        from taf.ul.sc.gnb.airscale import AirScale
        return AirScale(device_name=device_name, autoconnect=True).oam_type

    @staticmethod
    def _get_oam_class_name():
        if Rest.oam_type == 'MZOAM':
            return MegaZoneOAM
        else:
            return CommonOAM


__all__ = ['Rest']
